import { MigrationBuilder } from '../src/migrations/MigrationBuilder';
import { generateMigrationFromDiff } from '../src/migrations/DialectMigrationSql';

describe('Rename table/column', () => {
  test('table rename per dialect', () => {
    const mb = new MigrationBuilder().renameTable('a', 'b');
    const diff = mb.toDiff();
    expect(generateMigrationFromDiff(diff, 'postgresql').up[0]).toContain('RENAME TO');
    expect(generateMigrationFromDiff(diff, 'mysql').up[0]).toContain('RENAME TABLE');
    expect(generateMigrationFromDiff(diff, 'mssql').up[0]).toContain('sp_rename');
  });

  test('column rename emits dialect-specific SQL/comments', () => {
    const mb = new MigrationBuilder().renameColumn('t', 'old', 'new');
    const upPg = generateMigrationFromDiff(mb.toDiff(), 'postgresql').up;
    expect(upPg.some((s) => s.includes('RENAME COLUMN'))).toBeTruthy();
    const upMy = generateMigrationFromDiff(mb.toDiff(), 'mysql').up;
    expect(upMy.some((s) => s.startsWith('-- MySQL requires full type'))).toBeTruthy();
    const upSqlite = generateMigrationFromDiff(mb.toDiff(), 'sqlite').up;
    expect(upSqlite.some((s) => s.startsWith('-- SQLite column rename'))).toBeTruthy();
  });
});
